import { apiFetch } from "@/api/client";
import type { Paginated } from "@/api/types";

export interface OrderListItem {
  id: string;
  supplier_id: string;
  product_id: string;
  quantity: number;
  unit_price: number;
  total_price: number;
  status: string;
  priority: string;
  created_at: string;
  updated_at: string;
  warehouse: string | null;
  notes: string | null;
}

export interface OrderDetail extends OrderListItem {
  supplier_name: string;
  product_name: string;
}

export interface ListOrdersParams {
  limit: number;
  offset: number;
  signal?: AbortSignal;
}

export function listOrders({ limit, offset, signal }: ListOrdersParams) {
  const qs = new URLSearchParams({ limit: String(limit), offset: String(offset) });
  return apiFetch<Paginated<OrderListItem>>(`/api/orders?${qs}`, { signal });
}

export function getOrder(id: string, signal?: AbortSignal) {
  return apiFetch<OrderDetail>(`/api/orders/${encodeURIComponent(id)}`, { signal });
}

export interface PatchOrderBody {
  status: string;
}

export function patchOrder(id: string, body: PatchOrderBody, signal?: AbortSignal) {
  return apiFetch<OrderDetail>(`/api/orders/${encodeURIComponent(id)}`, {
    method: "PATCH",
    body,
    signal,
  });
}

