import { useQuery } from "@tanstack/react-query";
import { Sheet, SheetBody, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { ApiError } from "@/api/types";
import { getOrder } from "@/features/orders/api";
import { formatCurrency, formatDateTime, statusVariant } from "@/features/orders/format";

interface OrderDetailSheetProps {
  orderId: string | null;
  onClose: () => void;
}

export function OrderDetailSheet({ orderId, onClose }: OrderDetailSheetProps) {
  const open = orderId !== null;
  const query = useQuery({
    queryKey: ["order", orderId],
    queryFn: ({ signal }) => getOrder(orderId!, signal),
    enabled: open,
  });

  return (
    <Sheet open={open} onClose={onClose}>
      <SheetHeader>
        <SheetTitle>{orderId ?? ""}</SheetTitle>
        <SheetDescription>Order detail</SheetDescription>
      </SheetHeader>
      <SheetBody>
        {query.isPending && (
          <div className="space-y-3">
            <Skeleton className="h-4 w-3/4" />
            <Skeleton className="h-4 w-2/3" />
            <Skeleton className="h-4 w-1/2" />
          </div>
        )}
        {query.isError && (
          <p className="text-sm text-destructive">
            Failed to load order
            {query.error instanceof ApiError ? ` (${query.error.code})` : ""}
          </p>
        )}
        {query.data && (
          <dl className="grid grid-cols-[max-content_1fr] gap-x-6 gap-y-3 text-sm">
            <Field label="Status">
              <Badge variant={statusVariant(query.data.status)}>{query.data.status}</Badge>
            </Field>
            <Field label="Priority">{query.data.priority}</Field>
            <Field label="Supplier">
              <div className="font-medium">{query.data.supplier_name}</div>
              <div className="text-xs text-muted-foreground">{query.data.supplier_id}</div>
            </Field>
            <Field label="Product">
              <div className="font-medium">{query.data.product_name}</div>
              <div className="text-xs text-muted-foreground">{query.data.product_id}</div>
            </Field>
            <Field label="Quantity">{query.data.quantity}</Field>
            <Field label="Unit price">{formatCurrency(query.data.unit_price)}</Field>
            <Field label="Total">{formatCurrency(query.data.total_price)}</Field>
            <Field label="Warehouse">{query.data.warehouse ?? "—"}</Field>
            <Field label="Created">{formatDateTime(query.data.created_at)}</Field>
            <Field label="Updated">{formatDateTime(query.data.updated_at)}</Field>
            {query.data.notes && <Field label="Notes">{query.data.notes}</Field>}
          </dl>
        )}
      </SheetBody>
    </Sheet>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <>
      <dt className="text-muted-foreground">{label}</dt>
      <dd>{children}</dd>
    </>
  );
}

