1	using Dapper;
2	using Npgsql;
3	using OrderOps.Api.Infrastructure;
4	
5	namespace OrderOps.Api.Features.Orders;
6	
7	public sealed class OrderRepository : IOrderRepository
8	{
9	    private readonly NpgsqlDataSource _dataSource;
10	
11	    public OrderRepository(NpgsqlDataSource dataSource) => _dataSource = dataSource;
12	
13	    private const string DetailColumns = """
14	        o.id, o.supplier_id, o.product_id, o.quantity, o.unit_price, o.total_price,
15	        o.status, o.priority, o.created_at, o.updated_at, o.warehouse, o.notes,
16	        s.name AS supplier_name, p.name AS product_name
17	        """;
18	
19	    private const string ListColumns = """
20	        o.id, o.supplier_id, o.product_id, o.quantity, o.unit_price, o.total_price,
21	        o.status, o.priority, o.created_at, o.updated_at, o.warehouse, o.notes,
22	        p.name AS product_name
23	        """;
24	
25	    // Whitelist: API field name → SQL column. Anything not in this map falls back to o.id.
26	    private static readonly IReadOnlyDictionary<string, string> SortColumns =
27	        new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
28	        {
29	            ["id"]          = "o.id",
30	            ["created_at"]  = "o.created_at",
31	            ["updated_at"]  = "o.updated_at",
32	            ["total_price"] = "o.total_price",
33	            ["unit_price"]  = "o.unit_price",
34	            ["quantity"]    = "o.quantity",
35	            ["status"]      = "o.status",
36	            ["priority"]    = "o.priority",
37	            ["supplier_id"] = "o.supplier_id",
38	            ["warehouse"]   = "o.warehouse",
39	        };
40	
41	    public async Task<PagedResult<OrderListItem>> ListAsync(OrderListQuery q, CancellationToken ct)
42	    {
43	        var (where, parameters) = BuildWhere(q);
44	        var sortCol = q.Sort is not null && SortColumns.TryGetValue(q.Sort, out var c) ? c : "o.id";
45	        var sortDir = string.Equals(q.Order, "desc", StringComparison.OrdinalIgnoreCase) ? "DESC" : "ASC";
46	        var countJoin = string.IsNullOrEmpty(q.Search) ? "" : "JOIN products p ON p.id = o.product_id";
47	
48	        parameters.Add("limit", q.Limit);
49	        parameters.Add("offset", q.Offset);
50	
51	        var sql = $"""
52	            SELECT {ListColumns}
53	            FROM   orders o
54	            JOIN   products p ON p.id = o.product_id
55	            {where}
56	            ORDER  BY {sortCol} {sortDir}, o.id
57	            LIMIT  @limit OFFSET @offset;
58	
59	            SELECT count(*)
60	            FROM   orders o
61	            {countJoin}
62	            {where};
63	            """;
64	
65	        await using var conn = await _dataSource.OpenConnectionAsync(ct);
66	        await using var grid = await conn.QueryMultipleAsync(new CommandDefinition(
67	            sql, parameters, cancellationToken: ct));
68	
69	        var rows = (await grid.ReadAsync<OrderListItem>()).AsList();
70	        var total = await grid.ReadSingleAsync<long>();
71	        return new PagedResult<OrderListItem>(rows, total, q.Limit, q.Offset);
72	    }
73	
74	    private static (string Where, DynamicParameters P) BuildWhere(OrderListQuery q)
75	    {
76	        var clauses = new List<string>();
77	        var p = new DynamicParameters();
78	
79	        if (q.Statuses is { Count: > 0 })
80	        {
81	            clauses.Add("o.status = ANY(@statuses)");
82	            p.Add("statuses", q.Statuses.ToArray());
83	        }
84	        if (!string.IsNullOrEmpty(q.Priority))
85	        {
86	            clauses.Add("o.priority = @priority");
87	            p.Add("priority", q.Priority);
88	        }
89	        if (!string.IsNullOrEmpty(q.SupplierId))
90	        {
91	            clauses.Add("o.supplier_id = @supplier_id");
92	            p.Add("supplier_id", q.SupplierId);
93	        }
94	        if (!string.IsNullOrEmpty(q.Warehouse))
95	        {
96	            clauses.Add("o.warehouse = @warehouse");
97	            p.Add("warehouse", q.Warehouse);
98	        }
99	        if (q.DateFrom.HasValue)
100	        {
101	            clauses.Add("o.created_at >= @date_from");
102	            p.Add("date_from", q.DateFrom.Value);
103	        }
104	        if (q.DateTo.HasValue)
105	        {
106	            clauses.Add("o.created_at < @date_to + interval '1 day'");
107	            p.Add("date_to", q.DateTo.Value);
108	        }
109	        if (q.MinTotal.HasValue)
110	        {
111	            clauses.Add("o.total_price >= @min_total");
112	            p.Add("min_total", q.MinTotal.Value);
113	        }
114	        if (!string.IsNullOrEmpty(q.Search))
115	        {
116	            clauses.Add("p.name ILIKE '%' || @search || '%'");
117	            p.Add("search", q.Search);
118	        }
119	
120	        var where = clauses.Count == 0 ? "" : "WHERE " + string.Join(" AND ", clauses);
121	        return (where, p);
122	    }
123	
124	    public async Task<OrderDetail?> GetByIdAsync(string id, CancellationToken ct)
125	    {
126	        var sql = $"""
127	            SELECT {DetailColumns}
128	            FROM   orders o
129	            JOIN   suppliers s ON s.id = o.supplier_id
130	            JOIN   products  p ON p.id = o.product_id
131	            WHERE  o.id = @id;
