    public async Task<OrderStats> GetStatsAsync(CancellationToken ct)
    {
        var orders = _db.Orders.AsNoTracking();

        var totals = await orders
            .GroupBy(_ => 1)
            .Select(g => new
            {
                Count = g.LongCount(),
                Total = g.Sum(o => (decimal?)o.TotalPrice) ?? 0m,
                Avg = g.Average(o => (decimal?)o.TotalPrice) ?? 0m,
