               OR  o.unit_price > p.price * 1.5
               OR  extract(hour FROM o.created_at) < 8
               OR  extract(hour FROM o.created_at) >= 18
               OR  s.rating <= 1.5
            ORDER  BY o.id;
            """;

        var rows = await _db.Database.SqlQueryRaw<AnomalyRow>(sql).ToListAsync(ct);
        return rows;
    }
}

