using Microsoft.EntityFrameworkCore;
using Npgsql;
using NpgsqlTypes;
using OrderOps.Api.Data;
using OrderOps.Api.Data.Entities;

namespace OrderOps.Api.Features.Bulk;

public sealed class BulkRepository : IBulkRepository
{
    private readonly AppDbContext _db;

    public BulkRepository(AppDbContext db) => _db = db;

    public async Task InsertJobAsync(string id, string action, int total, CancellationToken ct)
    {
        _db.Jobs.Add(new Job
        {
            Id = id,
            Status = "processing",
            Total = total,
            Completed = 0,
            Failed = 0,
            Action = action,
            CreatedAt = DateTime.UtcNow,
        });
        await _db.SaveChangesAsync(ct);
    }

    public async Task<JobMirrorRow?> GetJobAsync(string id, CancellationToken ct)
    {
        var job = await _db.Jobs.AsNoTracking()
            .FirstOrDefaultAsync(j => j.Id == id, ct);
        if (job is null) return null;

        return new JobMirrorRow
        {
            Id = job.Id,
            Status = job.Status,
            Total = job.Total,
            Completed = job.Completed,
            Failed = job.Failed,
            Action = job.Action,
        };
    }

    public async Task FinalizeJobAsync(string id, string status, int completed, int failed, CancellationToken ct)
    {
        var job = await _db.Jobs.FirstOrDefaultAsync(j => j.Id == id, ct);
        if (job is null) return;
        job.Status = status;
        job.Completed = completed;
        job.Failed = failed;
        job.FinishedAt = DateTime.UtcNow;
        await _db.SaveChangesAsync(ct);
    }

    private sealed class LockedRow
    {
        public string id { get; set; } = "";
        public string status { get; set; } = "";
        public int version { get; set; }
    }

    public async Task<BulkChunkResult> ApplyChunkAsync(
        string jobId, string action, string? reason, string[] ids, CancellationToken ct)
    {
        if (ids.Length == 0) return new BulkChunkResult(0, 0);

        var existing = await _db.Orders.AsNoTracking()
            .Where(o => ids.Contains(o.Id))
            .Select(o => o.Id)
            .ToListAsync(ct);
        var existingSet = existing.ToHashSet(StringComparer.Ordinal);
        var nonexistent = ids.Length - existingSet.Count;

        await using var tx = await _db.Database.BeginTransactionAsync(ct);

        var idsParam = new NpgsqlParameter("ids", NpgsqlDbType.Array | NpgsqlDbType.Text) { Value = ids };
        var locked = await _db.Database
            .SqlQueryRaw<LockedRow>(
                "SELECT id, status, version FROM orders WHERE id = ANY({0}) FOR UPDATE SKIP LOCKED",
                idsParam)
            .ToListAsync(ct);

        var lockedIds = locked.Select(r => r.id).ToHashSet(StringComparer.Ordinal);
        var overlapCount = existingSet.Count(id => !lockedIds.Contains(id));

        var completed = overlapCount;
        var failed = nonexistent;

        if (action == BulkActions.Flag)
        {
            const string insertFlag = """
                INSERT INTO order_flags (order_id, source_job_id, reason)
                VALUES ({0}, {1}, {2})
                ON CONFLICT (order_id) DO NOTHING;
                """;

            foreach (var row in locked)
            {
                if (row.status == "cancelled") { failed++; continue; }
                var reasonParam = new NpgsqlParameter("reason", NpgsqlDbType.Text)
                {
                    Value = (object?)reason ?? DBNull.Value,
                };
                await _db.Database.ExecuteSqlRawAsync(
                    "INSERT INTO order_flags (order_id, source_job_id, reason) VALUES ({0}, {1}, @reason) ON CONFLICT (order_id) DO NOTHING",
                    new object[] { row.id, jobId, reasonParam }, ct);
                completed++;
            }
        }
        else
        {
            var newStatus = BulkActions.MapToStatus(action)
                ?? throw new InvalidOperationException($"unsupported action '{action}'");

            const string updateSql = """
                UPDATE orders
                SET    status = {0}, updated_at = now(), version = version + 1
                WHERE  id = {1} AND version = {2};
                """;

            foreach (var row in locked)
            {
                if (row.status == "cancelled") { failed++; continue; }
                var rows = await _db.Database.ExecuteSqlRawAsync(
                    updateSql, new object[] { newStatus, row.id, row.version }, ct);
                if (rows == 1) completed++;
                else failed++;
            }
        }

        await tx.CommitAsync(ct);
        return new BulkChunkResult(completed, failed);
    }
}

using Microsoft.EntityFrameworkCore;
using Npgsql;
using OrderOps.Api.Data;
using OrderOps.Api.Infrastructure;

namespace OrderOps.Api.Features.Products;

public sealed class ProductRepository : IProductRepository
{
    private readonly AppDbContext _db;

    public ProductRepository(AppDbContext db) => _db = db;

    public async Task<PagedResult<ProductListItem>> ListAsync(int limit, int offset, CancellationToken ct)
    {
        var total = await _db.Products.CountAsync(ct);

        var rows = await _db.Products.AsNoTracking()
            .OrderBy(p => p.Id)
            .Skip(offset).Take(limit)
            .Select(p => new ProductListItem(p.Id, p.Name, p.CategoryId, p.Sku, p.Price))
            .ToListAsync(ct);

        return new PagedResult<ProductListItem>(rows, total, limit, offset);
    }

    // Cycle guard via visited-array path: c.id = ANY(d.path) marks revisit; outer
    // WHERE NOT d.cycle blocks descent. Required because seed has cat_150↔151↔152.
    public async Task<PagedResult<ProductListItem>> ListByCategoryDescendantsAsync(
        string rootCategoryId, int limit, int offset, CancellationToken ct)
    {
        const string descendantsCte = """
            WITH RECURSIVE descendants AS (
                SELECT id, parent_id, ARRAY[id::text] AS path, false AS cycle
                FROM   categories
                WHERE  id = {0}
                UNION ALL
                SELECT c.id, c.parent_id, d.path || c.id::text, c.id::text = ANY(d.path)
                FROM   categories c
                JOIN   descendants d ON c.parent_id = d.id
                WHERE  NOT d.cycle
            )
            """;

        var rows = await _db.Database
            .SqlQueryRaw<ProductListItem>(
                descendantsCte + """
                SELECT id          AS "Id",
                       name        AS "Name",
                       category_id AS "CategoryId",
                       sku         AS "Sku",
                       price       AS "Price"
                FROM   products
                WHERE  category_id IN (SELECT id FROM descendants)
                ORDER  BY id
                LIMIT  {1} OFFSET {2};
                """,
                rootCategoryId, limit, offset)
            .ToListAsync(ct);

        var total = await _db.Database
            .SqlQueryRaw<long>(
                descendantsCte + """
                SELECT count(*)::bigint AS "Value"
                FROM   products
                WHERE  category_id IN (SELECT id FROM descendants);
                """,
                rootCategoryId)
            .FirstAsync(ct);

        return new PagedResult<ProductListItem>(rows, total, limit, offset);
    }
}

