echo "--- PATCH valid priority ---" && curl -s -X PATCH "http://localhost:3000/api/orders/$FIRST" -H 'Content-Type: application/json' -d '{"priority":"high"}' -w '
HTTP %{http_code}
' | head -3 && \
echo "--- PATCH invalid priority ---" && curl -s -X PATCH "http://localhost:3000/api/orders/$FIRST" -H 'Content-Type: application/json' -d '{"priority":"garbage"}' -w '
HTTP %{http_code}
' && \
echo "--- PATCH empty body ---" && curl -s -X PATCH "http://localhost:3000/api/orders/$FIRST" -H 'Content-Type: application/json' -d '{}' -w '
HTTP %{http_code}
' && \
echo "--- PATCH oversize notes (5KB) ---" && BIG=$(printf 'a%.0s' {1..5000}) && curl -s -X PATCH "http://localhost:3000/api/orders/$FIRST" -H 'Content-Type: application/json' -d "{"notes":"$BIG"}" -w '
HTTP %{http_code}
'

